	CHECK ((status = 'APPROVED' AND approved_at IS NOT NULL) OR (status <> 'APPROVED' AND approved_at IS NULL))
);

CREATE INDEX ix_rule_versions_status_created ON crosstax.rule_versions (status, created_at);

CREATE TABLE crosstax.rule_audit_records (
